// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// ═════════════════════════════════════════════════════════════════════════════
//  By: Kenezu ArtsLab  —  kenezu.xyz; @kenezuartzlab; 
//  Visit: flowbridge.space; @flowbridgeweb3
//
//  FlowBridgeRouter  v3.0  —  Registry-Router + Configurable Fee System
//  ─────────────────────────────────────────────────────────────────────────
//
//  SCALABILITY
//  • RouterRegistry  — add unlimited DEX routers (V2/V3) without redeploy
//  • BridgeRegistry  — add unlimited bridges + chains without redeploy
//  • Frontend reads both registries on-chain; auto-populates UI selectors
//
//  FEE SYSTEM  (NEW in v3)
//  • globalFeeBps       — protocol fee rate, owner-configurable (default 0 = 0.00%)
//  • Can be set to ZERO — free swaps, partnerships, promotions
//  • Can be raised up to maxFeeBps (default 500 = 5%, owner can lower ceiling)
//  • routerFeeBps[id]   — per-router override (e.g. new DEX gets 0% promo rate)
//  • bridgeFeeBps[id]   — per-bridge override
//  • feeExempt[address] — zero fee whitelist (partners, devs, DAO treasury)
//  • feeTreasury        — single on-chain recipient (no caller-supplied address)
//  • computeFee()       — view function frontend uses to display exact fee
//  • Fee pulled on top of swapAmount — user specifies net amount to swap
//
//  SECURITY (all v2 controls retained)
//  • SafeERC20, ReentrancyGuard, Ownable (2-step), Pausable
//  • WBOT unwrap fix for V3 token→native paths
//  • All registry entries validated before use
//
// ═════════════════════════════════════════════════════════════════════════════

// ─── Safety Primitives ───────────────────────────────────────────────────────

library SafeERC20 {
    function safeTransfer(IERC20 token, address to, uint256 value) internal {
        _call(token, abi.encodeCall(token.transfer, (to, value)));
    }
    function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _call(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }
    function safeApprove(IERC20 token, address spender, uint256 value) internal {
        if (value > 0 && token.allowance(address(this), spender) > 0)
            _call(token, abi.encodeCall(token.approve, (spender, 0)));
        _call(token, abi.encodeCall(token.approve, (spender, value)));
    }
    function _call(IERC20 token, bytes memory data) private {
        (bool ok, bytes memory ret) = address(token).call(data);
        require(ok, "SafeERC20: call failed");
        if (ret.length > 0) require(abi.decode(ret, (bool)), "SafeERC20: op failed");
    }
}

abstract contract ReentrancyGuard {
    uint256 private constant _IN = 2; uint256 private constant _OUT = 1;
    uint256 private _s = _OUT;
    modifier nonReentrant() { require(_s != _IN, "Reentrant"); _s = _IN; _; _s = _OUT; }
}

abstract contract Ownable {
    address private _owner; address private _pending;
    event OwnershipTransferStarted(address indexed prev, address indexed next);
    event OwnershipTransferred(address indexed prev, address indexed next);
    constructor(address init) { require(init != address(0),"Owner:zero"); _owner=init; emit OwnershipTransferred(address(0),init); }
    modifier onlyOwner() { require(msg.sender == _owner,"Owner:not owner"); _; }
    function owner() public view returns (address) { return _owner; }
    function transferOwnership(address n) external onlyOwner { _pending=n; emit OwnershipTransferStarted(_owner,n); }
    function acceptOwnership() external {
        require(msg.sender==_pending,"Owner:not pending");
        emit OwnershipTransferred(_owner,_pending); _owner=_pending; _pending=address(0);
    }
}

abstract contract Pausable is Ownable {
    bool private _paused;
    event Paused(address by); event Unpaused(address by);
    modifier whenNotPaused() { require(!_paused,"Paused"); _; }
    function paused() public view returns (bool) { return _paused; }
    function pause()   external onlyOwner { _paused=true;  emit Paused(msg.sender); }
    function unpause() external onlyOwner { _paused=false; emit Unpaused(msg.sender); }
}

// ─── External Interfaces ─────────────────────────────────────────────────────

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

interface IWTOKEN {
    function withdraw(uint256 amount) external;
    function deposit() external payable;
}

interface IUniswapV2Router {
    function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external returns (uint256[] memory amounts);
    function swapExactETHForTokens(uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external payable returns (uint256[] memory amounts);
    function swapExactTokensForETH(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external returns (uint256[] memory amounts);
    function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory amounts);
}

interface ISwapRouterV3 {
    struct ExactInputSingleParams {
        address tokenIn; address tokenOut; uint24 fee; address recipient;
        uint256 deadline; uint256 amountIn; uint256 amountOutMinimum; uint160 sqrtPriceLimitX96;
    }
    function exactInputSingle(ExactInputSingleParams calldata p) external payable returns (uint256 amountOut);
    struct ExactInputParams {
        bytes path; address recipient; uint256 deadline; uint256 amountIn; uint256 amountOutMinimum;
    }
    function exactInput(ExactInputParams calldata p) external payable returns (uint256 amountOut);
}

// ═════════════════════════════════════════════════════════════════════════════
//  FlowBridgeRouter v3.0
// ═════════════════════════════════════════════════════════════════════════════

contract FlowBridgeRouter is Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ─────────────────────────────────────────────────────────────────────────
    //  REGISTRIES
    // ─────────────────────────────────────────────────────────────────────────

    enum RouterType { V2, V3 }

    struct RouterEntry {
        address    router;
        RouterType rtype;
        address    wrappedNative; // WBOT / WBNB / WETH per router
        bool       active;
        string     name;          // "CaSwap V2", "BDex V3", "PancakeSwap V2"
        string     version;
    }

    struct BridgeEntry {
        address   bridge;
        bool      active;
        string    name;
        string    destChainName;
        uint256   destChainId;
        address[] supportedTokens;
    }

    mapping(uint256 => RouterEntry) public routers;
    uint256 public routerCount;

    mapping(uint256 => BridgeEntry) public bridges;
    uint256 public bridgeCount;

    // ─────────────────────────────────────────────────────────────────────────
    //  FEE SYSTEM
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice Global protocol fee in basis points. 8 = 0.08%.
    ///         Owner can set to 0 (free) or up to maxFeeBps.
    uint256 public globalFeeBps = 0;

    /// @notice Hard ceiling for globalFeeBps. Owner can lower this but not raise it
    ///         above the compile-time constant below.
    uint256 public maxFeeBps = 500;     // 5% — absolute owner-settable ceiling
    uint256 private constant ABS_MAX_FEE_BPS = 1000; // 10% — hardcoded compile-time floor

    /// @notice Address that receives all protocol fees.
    address public feeTreasury;

    /// @notice Per-router fee override in BPS.
    ///         0 = use globalFeeBps.
    ///         Use setRouterFeeBps(id, 0) to remove override and fall back to global.
    ///         Use the sentinel value type(uint256).max to mark as explicitly overridden to 0.
    mapping(uint256 => uint256) public routerFeeBps;

    /// @notice Per-bridge fee override in BPS. Same sentinel logic as routerFeeBps.
    mapping(uint256 => uint256) public bridgeFeeBps;

    /// @notice Addresses that pay zero fee on all operations.
    ///         Use for: partners, DAO treasury, dev wallets, promotional campaigns.
    mapping(address => bool) public feeExempt;

    // Sentinel: routerFeeBps[id] == OVERRIDE_ZERO means explicitly set to 0% (not "use global")
    uint256 private constant OVERRIDE_ZERO = type(uint256).max;

    // ─────────────────────────────────────────────────────────────────────────
    //  EVENTS
    // ─────────────────────────────────────────────────────────────────────────

    event RouterRegistered(uint256 indexed id, address indexed router, RouterType rtype, string name);
    event RouterStatusChanged(uint256 indexed id, bool active);
    event BridgeRegistered(uint256 indexed id, address indexed bridge, string name, string destChain, uint256 destChainId);
    event BridgeStatusChanged(uint256 indexed id, bool active);

    event SwapExecuted(uint256 indexed routerId, address indexed tokenIn, address indexed tokenOut, address sender, address recipient, uint256 swapAmount, uint256 amountOut, uint256 fee);
    event MultiHopExecuted(address indexed tokenIn, address indexed tokenOut, address sender, address recipient, uint256 amountIn, uint256 amountOut);
    event BridgeSubmitted(uint256 indexed bridgeId, address indexed token, address sender, uint256 bridgeAmount, uint256 fee, uint256 destChainId);
    event FeeCollected(address indexed token, address indexed treasury, uint256 amount);

    event GlobalFeeBpsSet(uint256 oldBps, uint256 newBps);
    event MaxFeeBpsSet(uint256 oldMax, uint256 newMax);
    event RouterFeeBpsSet(uint256 indexed routerId, uint256 bps);
    event BridgeFeeBpsSet(uint256 indexed bridgeId, uint256 bps);
    event FeeExemptSet(address indexed account, bool exempt);
    event FeeTreasurySet(address indexed oldTreasury, address indexed newTreasury);

    // ─────────────────────────────────────────────────────────────────────────
    //  CONSTRUCTOR
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @param _initialOwner  Admin wallet. Recommend Gnosis Safe on mainnet.
     * @param _feeTreasury   Initial fee recipient. Can be updated via setFeeTreasury().
     *
     * No router or bridge addresses at deploy. Everything is registered post-deploy.
     * Same contract bytecode works on every chain — registry entries differ per chain.
     */
    constructor(address _initialOwner, address _feeTreasury) Ownable(_initialOwner) {
        require(_feeTreasury != address(0), "Invalid treasury");
        feeTreasury = _feeTreasury;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  ADMIN — FEE CONFIGURATION
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Set the global protocol fee rate.
     * @param bps  Fee in basis points. 0 = free. Max = maxFeeBps (default 500 = 5%).
     *
     * Examples:
     *   setGlobalFeeBps(0)   → 0.00% — completely free, no fee collected on any swap
     *   setGlobalFeeBps(5)   → 0.05%
     *   setGlobalFeeBps(8)   → 0.08% 
     *   setGlobalFeeBps(50)  → 0.50%
     *   setGlobalFeeBps(100) → 1.00%
     *   setGlobalFeeBps(500) → 5.00% (maxFeeBps ceiling)
     */
    function setGlobalFeeBps(uint256 bps) external onlyOwner {
        require(bps <= maxFeeBps, "Exceeds maxFeeBps");
        emit GlobalFeeBpsSet(globalFeeBps, bps);
        globalFeeBps = bps;
    }

    /**
     * @notice Lower (or raise, up to ABS_MAX_FEE_BPS) the maximum allowed fee.
     *         Useful to commit to a fee ceiling for community trust.
     *         Cannot exceed ABS_MAX_FEE_BPS (10% — compile-time constant).
     */
    function setMaxFeeBps(uint256 newMax) external onlyOwner {
        require(newMax <= ABS_MAX_FEE_BPS, "Exceeds absolute max (10%)");
        require(newMax >= globalFeeBps,    "New max below current global fee");
        emit MaxFeeBpsSet(maxFeeBps, newMax);
        maxFeeBps = newMax;
    }

    /**
     * @notice Set a fee override for a specific registered router.
     *
     * @param routerId  Target router ID.
     * @param bps       Fee BPS for this router. 0 = revert to global fee.
     *                  Pass type(uint256).max (OVERRIDE_ZERO) to explicitly set 0%
     *                  while keeping globalFeeBps non-zero for other routers.
     *
     * Examples (globalFeeBps = 8):
     *   setRouterFeeBps(2, 0)                     → NewDEX uses global 0.08%
     *   setRouterFeeBps(2, type(uint256).max)     → NewDEX is fee-free (0%), others pay 0.08%
     *   setRouterFeeBps(2, 3)                     → NewDEX charges 0.03% (promotional rate)
     *   setRouterFeeBps(2, 50)                    → NewDEX charges 0.50%
     */
    function setRouterFeeBps(uint256 routerId, uint256 bps) external onlyOwner {
        require(routerId < routerCount, "Router not found");
        require(bps == OVERRIDE_ZERO || bps <= maxFeeBps, "Exceeds maxFeeBps");
        routerFeeBps[routerId] = bps;
        emit RouterFeeBpsSet(routerId, bps);
    }

    /**
     * @notice Set a fee override for a specific bridge.
     *         Same sentinel logic as setRouterFeeBps.
     */
    function setBridgeFeeBps(uint256 bridgeId, uint256 bps) external onlyOwner {
        require(bridgeId < bridgeCount, "Bridge not found");
        require(bps == OVERRIDE_ZERO || bps <= maxFeeBps, "Exceeds maxFeeBps");
        bridgeFeeBps[bridgeId] = bps;
        emit BridgeFeeBpsSet(bridgeId, bps);
    }

    /**
     * @notice Exempt or un-exempt an address from fees on all operations.
     *
     * @param account  Address to exempt.
     * @param exempt   true = no fee ever. false = normal fee applies.
     *
     * Use for: DAO treasury, partner protocols, developer/test wallets,
     *          promotional campaigns with specific partner addresses.
     */
    function setFeeExempt(address account, bool exempt) external onlyOwner {
        require(account != address(0), "Zero address");
        feeExempt[account] = exempt;
        emit FeeExemptSet(account, exempt);
    }

    /**
     * @notice Update the fee treasury address.
     */
    function setFeeTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "Zero address");
        emit FeeTreasurySet(feeTreasury, newTreasury);
        feeTreasury = newTreasury;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  FEE COMPUTATION (public view — frontend calls this to display fee)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Compute the protocol fee for a swap through a given router.
     *
     * @param routerId   Router being used (0 if not applicable, e.g. bridge query).
     * @param swapAmount The net amount being swapped (fee is added ON TOP of this).
     * @param user       The swapping address (checked for feeExempt).
     * @return fee       Token amount charged as fee. 0 if exempt or rate is 0.
     * @return effectiveBps The BPS rate that was applied.
     *
     * Frontend usage:
     *   const { fee, effectiveBps } = await router.computeRouterFee(routerId, swapAmount, userAddr);
     *   // Display: "Fee: 0.08% = 0.08 USDT"
     *   // User approves: swapAmount + fee
     */
    function computeRouterFee(
        uint256 routerId,
        uint256 swapAmount,
        address user
    ) public view returns (uint256 fee, uint256 effectiveBps) {
        if (feeExempt[user]) return (0, 0);

        uint256 override_ = routerFeeBps[routerId];
        if (override_ == OVERRIDE_ZERO) return (0, 0);         // explicitly free router
        effectiveBps = override_ > 0 ? override_ : globalFeeBps;
        fee = (swapAmount * effectiveBps) / 10_000;
    }

    /**
     * @notice Compute the protocol fee for a bridge operation.
     */
    function computeBridgeFee(
        uint256 bridgeId,
        uint256 bridgeAmount,
        address user
    ) public view returns (uint256 fee, uint256 effectiveBps) {
        if (feeExempt[user]) return (0, 0);

        uint256 override_ = bridgeFeeBps[bridgeId];
        if (override_ == OVERRIDE_ZERO) return (0, 0);
        effectiveBps = override_ > 0 ? override_ : globalFeeBps;
        fee = (bridgeAmount * effectiveBps) / 10_000;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  INTERNAL FEE HELPERS
    // ─────────────────────────────────────────────────────────────────────────

    function _takeFee(address token, uint256 fee) internal {
        if (fee > 0 && feeTreasury != address(0)) {
            IERC20(token).safeTransfer(feeTreasury, fee);
            emit FeeCollected(token, feeTreasury, fee);
        }
    }

    function _takeNativeFee(uint256 fee) internal {
        if (fee > 0 && feeTreasury != address(0)) {
            (bool ok,) = feeTreasury.call{value: fee}("");
            require(ok, "Native fee failed");
            emit FeeCollected(address(0), feeTreasury, fee);
        }
    }

    function _validateDeadline(uint256 deadline) internal view {
        require(deadline >= block.timestamp, "Deadline passed");
    }

    function _requireRouter(uint256 routerId) internal view returns (RouterEntry storage r) {
        require(routerId < routerCount, "Router not found");
        r = routers[routerId];
        require(r.active, "Router inactive");
    }

    function _requireBridge(uint256 bridgeId) internal view returns (BridgeEntry storage b) {
        require(bridgeId < bridgeCount, "Bridge not found");
        b = bridges[bridgeId];
        require(b.active, "Bridge inactive");
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  ADMIN — ROUTER REGISTRY
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Register a new DEX router. Zero redeploy. Active immediately.
     *
     * @param router         DEX router contract address.
     * @param rtype          RouterType.V2 or RouterType.V3.
     * @param wrappedNative  WBOT/WBNB/WETH for native swaps on this router.
     * @param name           Display name shown in UI: "CaSwap V2", "BDex V3".
     * @param version        Version string: "2.0", "3.1".
     * @return routerId      Assigned registry ID.
     */
    function registerRouter(
        address router, RouterType rtype, address wrappedNative,
        string calldata name, string calldata version
    ) external onlyOwner returns (uint256 routerId) {
        require(router        != address(0), "Invalid router");
        require(wrappedNative != address(0), "Invalid wrappedNative");
        require(bytes(name).length > 0,      "Name required");
        routerId = routerCount++;
        routers[routerId] = RouterEntry(router, rtype, wrappedNative, true, name, version);
        emit RouterRegistered(routerId, router, rtype, name);
    }

    function setRouterActive(uint256 routerId, bool active) external onlyOwner {
        require(routerId < routerCount, "Router not found");
        routers[routerId].active = active;
        emit RouterStatusChanged(routerId, active);
    }

    function updateRouterWrappedNative(uint256 routerId, address newWN) external onlyOwner {
        require(routerId < routerCount,  "Router not found");
        require(newWN   != address(0),   "Invalid address");
        routers[routerId].wrappedNative = newWN;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  ADMIN — BRIDGE REGISTRY
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Register a new bridge. Zero redeploy. Appears in UI immediately.
     *
     * @param bridge          Bridge contract on this chain (entry/lock point).
     * @param name            Display name: "LayerZero BOT→BNB".
     * @param destChainName   Human-readable: "BNB Smart Chain".
     * @param destChainId     EVM chain ID (56=BNB, 1=ETH, 137=Polygon, 0=non-EVM).
     * @param supportedTokens ERC-20 tokens this bridge accepts.
     * @return bridgeId       Assigned registry ID.
     */
    function registerBridge(
        address bridge, string calldata name, string calldata destChainName,
        uint256 destChainId, address[] calldata supportedTokens
    ) external onlyOwner returns (uint256 bridgeId) {
        require(bridge != address(0),   "Invalid bridge");
        require(bytes(name).length > 0, "Name required");
        bridgeId = bridgeCount++;
        bridges[bridgeId] = BridgeEntry(bridge, true, name, destChainName, destChainId, supportedTokens);
        emit BridgeRegistered(bridgeId, bridge, name, destChainName, destChainId);
    }

    function setBridgeActive(uint256 bridgeId, bool active) external onlyOwner {
        require(bridgeId < bridgeCount, "Bridge not found");
        bridges[bridgeId].active = active;
        emit BridgeStatusChanged(bridgeId, active);
    }

    function updateBridgeSupportedTokens(uint256 bridgeId, address[] calldata tokens) external onlyOwner {
        require(bridgeId < bridgeCount, "Bridge not found");
        bridges[bridgeId].supportedTokens = tokens;
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 1 — V2 TOKEN → TOKEN
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * @notice Swap ERC-20 → ERC-20 via any registered V2 router.
     *         Fee is computed on-chain from the FeeSystem — no caller-supplied amount.
     *
     * @param routerId    Registry ID of the V2 router to use.
     * @param swapAmount  Net amount to swap (fee added on top; approve swapAmount + fee).
     * @param amountOutMin Slippage guard on output.
     * @param path        Token path: [tokenIn, tokenOut] or multi-hop within same DEX.
     * @param to          Output recipient.
     * @param deadline    Unix timestamp.
     *
     * Approval required: swapAmount + computeRouterFee(routerId, swapAmount, msg.sender).fee
     */
    function swapV2(
        uint256  routerId,
        uint256  swapAmount,
        uint256  amountOutMin,
        address[] calldata path,
        address  to,
        uint256  deadline
    ) external nonReentrant whenNotPaused returns (uint256[] memory amounts) {
        require(swapAmount > 0,   "Zero amount");
        require(path.length >= 2, "Path too short");
        require(to != address(0), "Invalid recipient");
        _validateDeadline(deadline);

        RouterEntry storage r = _requireRouter(routerId);
        require(r.rtype == RouterType.V2, "Not a V2 router");

        (uint256 fee,) = computeRouterFee(routerId, swapAmount, msg.sender);
        uint256 totalIn = swapAmount + fee;

        IERC20(path[0]).safeTransferFrom(msg.sender, address(this), totalIn);
        _takeFee(path[0], fee);

        IERC20(path[0]).safeApprove(r.router, swapAmount);
        amounts = IUniswapV2Router(r.router).swapExactTokensForTokens(
            swapAmount, amountOutMin, path, to, deadline
        );

        emit SwapExecuted(routerId, path[0], path[path.length-1], msg.sender, to, swapAmount, amounts[amounts.length-1], fee);
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 2 — V3 SINGLE-HOP TOKEN → TOKEN
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * @notice Swap ERC-20 → ERC-20 via any registered V3 router (single hop).
     *
     * @param routerId         Registry ID of the V3 router.
     * @param tokenIn          Input ERC-20.
     * @param tokenOut         Output ERC-20.
     * @param feePool          V3 pool tier: 500 / 3000 / 10000.
     * @param swapAmount       Net swap amount (protocol fee added on top).
     * @param amountOutMinimum Slippage guard.
     * @param to               Output recipient.
     * @param deadline         Unix timestamp.
     */
    function swapV3Single(
        uint256 routerId,
        address tokenIn,
        address tokenOut,
        uint24  feePool,
        uint256 swapAmount,
        uint256 amountOutMinimum,
        address to,
        uint256 deadline
    ) external nonReentrant whenNotPaused returns (uint256 amountOut) {
        require(swapAmount > 0,         "Zero amount");
        require(tokenIn  != address(0), "Invalid tokenIn");
        require(tokenOut != address(0), "Invalid tokenOut");
        require(tokenIn  != tokenOut,   "Identical tokens");
        require(to       != address(0), "Invalid recipient");
        _validateDeadline(deadline);

        RouterEntry storage r = _requireRouter(routerId);
        require(r.rtype == RouterType.V3, "Not a V3 router");

        (uint256 fee,) = computeRouterFee(routerId, swapAmount, msg.sender);
        uint256 totalIn = swapAmount + fee;

        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), totalIn);
        _takeFee(tokenIn, fee);

        IERC20(tokenIn).safeApprove(r.router, swapAmount);
        amountOut = ISwapRouterV3(r.router).exactInputSingle(
            ISwapRouterV3.ExactInputSingleParams({
                tokenIn: tokenIn, tokenOut: tokenOut, fee: feePool, recipient: to,
                deadline: deadline, amountIn: swapAmount,
                amountOutMinimum: amountOutMinimum, sqrtPriceLimitX96: 0
            })
        );

        emit SwapExecuted(routerId, tokenIn, tokenOut, msg.sender, to, swapAmount, amountOut, fee);
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 3 — V3 MULTI-HOP ENCODED PATH
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * @notice V3 multi-hop swap via encoded path.
     *         Path encoding: abi.encodePacked(token0, fee01, token1, fee12, token2, ...)
     *
     * @param routerId         V3 router registry ID.
     * @param tokenIn          First token in path.
     * @param tokenOut         Last token in path.
     * @param encodedPath      ABI-packed V3 path bytes.
     * @param swapAmount       Net swap amount.
     * @param amountOutMinimum Final slippage guard.
     * @param to               Output recipient.
     * @param deadline         Unix timestamp.
     */
    function swapV3Multi(
        uint256 routerId,
        address tokenIn,
        address tokenOut,
        bytes   calldata encodedPath,
        uint256 swapAmount,
        uint256 amountOutMinimum,
        address to,
        uint256 deadline
    ) external nonReentrant whenNotPaused returns (uint256 amountOut) {
        require(swapAmount > 0,           "Zero amount");
        require(tokenIn    != address(0), "Invalid tokenIn");
        require(encodedPath.length >= 43, "Path too short");
        require(to         != address(0), "Invalid recipient");
        _validateDeadline(deadline);

        RouterEntry storage r = _requireRouter(routerId);
        require(r.rtype == RouterType.V3, "Not a V3 router");

        (uint256 fee,) = computeRouterFee(routerId, swapAmount, msg.sender);
        uint256 totalIn = swapAmount + fee;

        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), totalIn);
        _takeFee(tokenIn, fee);

        IERC20(tokenIn).safeApprove(r.router, swapAmount);
        amountOut = ISwapRouterV3(r.router).exactInput(
            ISwapRouterV3.ExactInputParams({
                path: encodedPath, recipient: to, deadline: deadline,
                amountIn: swapAmount, amountOutMinimum: amountOutMinimum
            })
        );

        emit SwapExecuted(routerId, tokenIn, tokenOut, msg.sender, to, swapAmount, amountOut, fee);
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 4 — NATIVE → TOKEN
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * @notice Swap native gas token (BOT/BNB/ETH) → ERC-20 via any registered router.
     *         Fee is deducted from msg.value. Remaining goes to the swap.
     *         msg.value = swapAmount + fee (use computeRouterFee view to calculate).
     *
     * @param routerId    Registry ID (V2 or V3).
     * @param tokenOut    Target ERC-20.
     * @param feePool     V3 pool fee tier (ignored for V2).
     * @param amountOutMin Slippage guard.
     * @param path        For V2: [WBOT, tokenOut]. Ignored for V3.
     * @param to          Output recipient.
     * @param deadline    Unix timestamp.
     */
    function swapNativeToToken(
        uint256  routerId,
        address  tokenOut,
        uint24   feePool,
        uint256  amountOutMin,
        address[] calldata path,
        address  to,
        uint256  deadline
    ) external payable nonReentrant whenNotPaused returns (uint256 amountOut) {
        require(msg.value > 0,      "Zero value");
        require(tokenOut != address(0), "Invalid tokenOut");
        require(to       != address(0), "Invalid recipient");
        _validateDeadline(deadline);

        RouterEntry storage r = _requireRouter(routerId);

        // Fee is a fraction of msg.value — computed on the net swap portion
        // swapAmount = msg.value / (1 + feeBps/10000)  ≈ msg.value * 10000 / (10000 + feeBps)
        (uint256 effectiveBps) = _getNativeEffectiveBps(routerId, msg.sender);
        uint256 fee        = (msg.value * effectiveBps) / (10_000 + effectiveBps);
        uint256 swapAmount = msg.value - fee;

        _takeNativeFee(fee);

        if (r.rtype == RouterType.V2) {
            require(path.length >= 2, "Path too short");
            uint256[] memory amounts = IUniswapV2Router(r.router).swapExactETHForTokens{value: swapAmount}(
                amountOutMin, path, to, deadline
            );
            amountOut = amounts[amounts.length - 1];
        } else {
            amountOut = ISwapRouterV3(r.router).exactInputSingle{value: swapAmount}(
                ISwapRouterV3.ExactInputSingleParams({
                    tokenIn: r.wrappedNative, tokenOut: tokenOut, fee: feePool, recipient: to,
                    deadline: deadline, amountIn: swapAmount,
                    amountOutMinimum: amountOutMin, sqrtPriceLimitX96: 0
                })
            );
        }

        emit SwapExecuted(routerId, address(0), tokenOut, msg.sender, to, swapAmount, amountOut, fee);
    }

    function _getNativeEffectiveBps(uint256 routerId, address user) internal view returns (uint256) {
        if (feeExempt[user]) return 0;
        uint256 override_ = routerFeeBps[routerId];
        if (override_ == OVERRIDE_ZERO) return 0;
        return override_ > 0 ? override_ : globalFeeBps;
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 5 — TOKEN → NATIVE
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * @notice Swap ERC-20 → native gas token via any registered router.
     *         V3 path: auto-unwraps WBOT → native BOT.
     *
     * @param routerId     Registry ID (V2 or V3).
     * @param tokenIn      Input ERC-20.
     * @param feePool      V3 pool fee tier (ignored for V2).
     * @param swapAmount   Net swap amount (fee added on top on approval).
     * @param amountOutMin Slippage guard on native output.
     * @param path         For V2: [tokenIn, WBOT]. Ignored for V3.
     * @param to           Native token recipient.
     * @param deadline     Unix timestamp.
     */
    function swapTokenToNative(
        uint256  routerId,
        address  tokenIn,
        uint24   feePool,
        uint256  swapAmount,
        uint256  amountOutMin,
        address[] calldata path,
        address payable to,
        uint256  deadline
    ) external nonReentrant whenNotPaused returns (uint256 amountOut) {
        require(swapAmount > 0,       "Zero amount");
        require(tokenIn != address(0),"Invalid tokenIn");
        require(to      != address(0),"Invalid recipient");
        _validateDeadline(deadline);

        RouterEntry storage r = _requireRouter(routerId);

        (uint256 fee,) = computeRouterFee(routerId, swapAmount, msg.sender);
        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), swapAmount + fee);
        _takeFee(tokenIn, fee);

        if (r.rtype == RouterType.V2) {
            require(path.length >= 2, "Path too short");
            IERC20(tokenIn).safeApprove(r.router, swapAmount);
            uint256[] memory amounts = IUniswapV2Router(r.router).swapExactTokensForETH(
                swapAmount, amountOutMin, path, to, deadline
            );
            amountOut = amounts[amounts.length - 1];
        } else {
            IERC20(tokenIn).safeApprove(r.router, swapAmount);
            amountOut = ISwapRouterV3(r.router).exactInputSingle(
                ISwapRouterV3.ExactInputSingleParams({
                    tokenIn: tokenIn, tokenOut: r.wrappedNative, fee: feePool,
                    recipient: address(this), deadline: deadline,
                    amountIn: swapAmount, amountOutMinimum: amountOutMin, sqrtPriceLimitX96: 0
                })
            );
            IWTOKEN(r.wrappedNative).withdraw(amountOut);
            (bool ok,) = to.call{value: amountOut}("");
            require(ok, "Native delivery failed");
        }

        emit SwapExecuted(routerId, tokenIn, address(0), msg.sender, to, swapAmount, amountOut, fee);
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 6 — MULTI-HOP CROSS-ROUTER (CA→BOT→USDT in one tx)
    // ═════════════════════════════════════════════════════════════════════════

    struct HopParams {
        uint256   routerId;
        address[] path;
        uint256   amountOutMin; // per-hop slippage floor
    }

    /**
     * @notice Atomically chain multiple swaps across different registered routers.
     *         Fee is taken once on the initial input amount.
     *
     * @param hops         Array of HopParams. Min 2, max 10.
     * @param swapAmount   Net amount of hops[0].path[0] to swap.
     * @param to           Final output recipient.
     * @param deadline     Global deadline applied to every hop.
     *
     * Example — CA → BOT → USDT:
     *   hops[0]: routerId=0 (CaSwap V2), path=[CA,BOT],   amountOutMin=minBOT
     *   hops[1]: routerId=0 (BDex V2),   path=[BOT,USDT], amountOutMin=minUSDT
     */
    function swapMultiHop(
        HopParams[] calldata hops,
        uint256     swapAmount,
        address     to,
        uint256     deadline
    ) external nonReentrant whenNotPaused returns (uint256 finalAmountOut) {
        require(hops.length >= 2 && hops.length <= 10, "Hops: 2-10");
        require(swapAmount > 0,   "Zero amount");
        require(to != address(0), "Invalid recipient");
        _validateDeadline(deadline);

        address tokenIn = hops[0].path[0];

        // Fee taken once on the initial input using the first hop's routerId
        (uint256 fee,) = computeRouterFee(hops[0].routerId, swapAmount, msg.sender);
        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), swapAmount + fee);
        _takeFee(tokenIn, fee);

        address lastToken  = tokenIn;
        uint256 currentAmt = swapAmount;

        for (uint256 i = 0; i < hops.length; i++) {
            HopParams calldata hop = hops[i];
            require(hop.path.length >= 2,     "Hop path too short");
            require(hop.path[0] == lastToken, "Hop token mismatch");

            RouterEntry storage r = _requireRouter(hop.routerId);
            require(r.rtype == RouterType.V2,  "Multi-hop: V2 only");

            address hopTo = (i == hops.length - 1) ? to : address(this);
            IERC20(lastToken).safeApprove(r.router, currentAmt);

            uint256[] memory amounts = IUniswapV2Router(r.router).swapExactTokensForTokens(
                currentAmt, hop.amountOutMin, hop.path, hopTo, deadline
            );
            lastToken  = hop.path[hop.path.length - 1];
            currentAmt = amounts[amounts.length - 1];
        }

        finalAmountOut = currentAmt;
        emit MultiHopExecuted(hops[0].path[0], lastToken, msg.sender, to, swapAmount, finalAmountOut);
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 7 — BRIDGE WITH FEE
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * @notice Collect protocol fee and forward remainder to any registered bridge.
     *         Bridge handles cross-chain delivery — this router is a non-custodial proxy.
     *
     * @param bridgeId    Registry ID of the target bridge.
     * @param token       ERC-20 to bridge (must be in bridge's supportedTokens).
     * @param bridgeAmount Net amount to bridge (fee added on top on approval).
     *
     * Approval required: bridgeAmount + computeBridgeFee(bridgeId, bridgeAmount, msg.sender).fee
     */
    function bridgeWithFee(
        uint256 bridgeId,
        address token,
        uint256 bridgeAmount
    ) external nonReentrant whenNotPaused returns (bool) {
        require(bridgeAmount > 0,   "Zero amount");
        require(token != address(0),"Invalid token");

        BridgeEntry storage b = _requireBridge(bridgeId);

        bool supported;
        for (uint256 i = 0; i < b.supportedTokens.length; i++) {
            if (b.supportedTokens[i] == token) { supported = true; break; }
        }
        require(supported, "Token not supported by bridge");

        (uint256 fee,) = computeBridgeFee(bridgeId, bridgeAmount, msg.sender);
        IERC20(token).safeTransferFrom(msg.sender, address(this), bridgeAmount + fee);
        _takeFee(token, fee);

        IERC20(token).safeTransfer(b.bridge, bridgeAmount);
        emit BridgeSubmitted(bridgeId, token, msg.sender, bridgeAmount, fee, b.destChainId);
        return true;
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 8 — FRONTEND VIEW HELPERS
    // ═════════════════════════════════════════════════════════════════════════

    function getActiveRouters() external view returns (
        uint256[] memory ids, string[] memory names,
        string[] memory versions, RouterType[] memory types, address[] memory addrs
    ) {
        uint256 cnt;
        for (uint256 i = 0; i < routerCount; i++) if (routers[i].active) cnt++;
        ids = new uint256[](cnt); names = new string[](cnt);
        versions = new string[](cnt); types = new RouterType[](cnt); addrs = new address[](cnt);
        uint256 idx;
        for (uint256 i = 0; i < routerCount; i++) {
            if (routers[i].active) {
                ids[idx]=i; names[idx]=routers[i].name; versions[idx]=routers[i].version;
                types[idx]=routers[i].rtype; addrs[idx]=routers[i].router; idx++;
            }
        }
    }

    function getActiveBridges() external view returns (
        uint256[] memory ids, string[] memory names,
        string[] memory destChainNames, uint256[] memory destChainIds, address[] memory addrs
    ) {
        uint256 cnt;
        for (uint256 i = 0; i < bridgeCount; i++) if (bridges[i].active) cnt++;
        ids = new uint256[](cnt); names = new string[](cnt);
        destChainNames = new string[](cnt); destChainIds = new uint256[](cnt); addrs = new address[](cnt);
        uint256 idx;
        for (uint256 i = 0; i < bridgeCount; i++) {
            if (bridges[i].active) {
                ids[idx]=i; names[idx]=bridges[i].name; destChainNames[idx]=bridges[i].destChainName;
                destChainIds[idx]=bridges[i].destChainId; addrs[idx]=bridges[i].bridge; idx++;
            }
        }
    }

    function getBridgeSupportedTokens(uint256 bridgeId) external view returns (address[] memory) {
        require(bridgeId < bridgeCount, "Bridge not found");
        return bridges[bridgeId].supportedTokens;
    }

    function getBestV2Rate(uint256 amountIn, address[] calldata path)
        external view returns (uint256 bestRouterId, uint256 bestAmountOut, uint256[] memory allAmountsOut)
    {
        require(path.length >= 2, "Path too short");
        allAmountsOut = new uint256[](routerCount);
        for (uint256 i = 0; i < routerCount; i++) {
            RouterEntry storage r = routers[i];
            if (!r.active || r.rtype != RouterType.V2) continue;
            try IUniswapV2Router(r.router).getAmountsOut(amountIn, path) returns (uint256[] memory amounts) {
                uint256 out = amounts[amounts.length - 1];
                allAmountsOut[i] = out;
                if (out > bestAmountOut) { bestAmountOut = out; bestRouterId = i; }
            } catch { allAmountsOut[i] = 0; }
        }
    }

    /**
     * @notice Returns the full fee configuration at a glance.
     *         Frontend calls this once on load to display fee info.
     */
    function getFeeConfig() external view returns (
        uint256 _globalFeeBps,
        uint256 _maxFeeBps,
        address _feeTreasury
    ) {
        return (globalFeeBps, maxFeeBps, feeTreasury);
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SECTION 9 — ADMIN UTILITIES
    // ═════════════════════════════════════════════════════════════════════════

    function rescueERC20(address token, address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        IERC20(token).safeTransfer(to, amount);
    }

    function rescueNative(address payable to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        (bool ok,) = to.call{value: amount}(""); require(ok, "Rescue failed");
    }

    receive() external payable {}
}
